const child = require('child_process');
const extHost = child.fork('./extension-host.js', [], {
  execArgv: ['--experimental-vm-modules'],
  serialization: 'advanced'
});
// Typed IPC through capability-scoped MessagePort
const { port1, port2 } = new MessageChannel();
extHost.send({ type: 'init', port: port2 }, [port2]);
port1.on('message', handleCapabilityRequest);

class CapabilityHandle {
  constructor(resource, rights, constraints = {}) {
    this.#resource = resource;    // e.g., 'files:/src/**'
    this.#rights = rights;        // e.g., Set(['read'])
    this.#constraints = constraints; // e.g., { maxBytes: 1048576 }
    Object.freeze(this);
  }
  attest(operation, target) {
    return this.#rights.has(operation) &&
           this.#matchesResource(target) &&
           this.#satisfiesConstraints(operation, target);
  }
  attenuate(subRights, subConstraints) {
    return new CapabilityHandle(
      this.#resource,
      intersection(this.#rights, subRights),
      { ...this.#constraints, ...subConstraints }
    );
  }
}

type PluginMessage =
  | { type: 'intent'; capability: string; action: string; payload: unknown; correlationId: string }
  | { type: 'subscribe'; event: string; capability: CapabilityHandle }
  | { type: 'response'; correlationId: string; status: 'ok' | 'denied' | 'error'; data?: unknown };

function validateAndDispatch(msg: PluginMessage, capabilities: Map<string, CapabilityHandle>) {
  const cap = capabilities.get(msg.capability);
  if (!cap || !cap.attest(msg.type, msg.action)) {
    return { status: 'denied', reason: 'capability not granted' };
  }
  // Route to governed handler
}
